def algorithm(func, dim, lb, ub, budget, rng):
    x = np.random.uniform(lb, ub, size=dim)
    best_x = x.copy()
    best_y = func(x)

    for t in range(budget):
        # Random Search (RS) phase
        if t < budget // 2:
            new_x = np.clip(rng.normal(loc=x, scale=np.sqrt(0.1), size=dim), a_min=lb, a_max=ub)
        else:
            # Cyclic Coordinate Descent (CCD) phase
            idx = (t + np.arange(dim)) % dim
            new_x = x.copy()
            for i in idx:
                new_x[i] = np.clip(rng.normal(loc=new_x[i], scale=np.sqrt(0.1), size=1)[0], a_min=lb, a_max=ub)

        new_y = func(new_x)

        if new_y < best_y:
            best_x = new_x.copy()
            best_y = new_y

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    best_x = None
    best_f = float('inf')

    for _ in range(budget):
        x = [np.random.uniform(lb, ub) for _ in range(dim)]

        f = func(x)

        if f < best_f:
            best_f = f
            best_x = np.array(x)

    return best_x

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, a_min=lb, a_max=ub)

    best_x = clip(rng.uniform(low=lb, high=ub, size=(dim)))
    best_f = func(best_x)

    for _ in range(budget):
        x = clip(rng.normal(loc=best_x, scale=0.1, size=(dim)))
        f = func(x)

        if f < best_f:
            best_f = f
            best_x = x

    return best_x
